// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address attacker, uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 1, 1 ether);
        vm.assume(attacker != address(this));

        vm.deal(attacker, 1 ether);

        vm.deal(address(this), fundAmount);
        payable(address(c)).transfer(fundAmount);
        uint256 before = address(c).balance;
        assertEq(before, fundAmount);

        vm.prank(attacker);
        bool ok;
        try c.withdrawAll(attacker) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == before);
    }
}
